def icon(n):return '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+paths.get(n,paths['file'])+'</svg>'
def btn(t,n='arrow',kind=''):return f'<button class="btn {kind}">{icon(n)}<span>{t}</span></button>'
def tag(t,c='indigo',n=None):return f'<span class="tag {c}">{icon(n) if n else ""}{t}</span>'
def head(title,sub='',back=False):return f'<header>{"<a class=back href=gallery.html>"+icon("back")+"Back</a>" if back else ""}<div class="row"><h1>{title}</h1><button class="iconbtn" aria-label="Settings">{icon("settings")}</button></div><p>{sub}</p></header>'
def nav(active='today'):return '<nav class="bottom">'+''.join(f'<a class="{"active" if k==active else ""}" href="after-{k}.html">{icon(i)}<span>{v}</span></a>' for k,i,v in [('today','sun','Today'),('schedule','calendar','Schedule'),('tasks','tasks','Tasks'),('pgce','book','PGCE file')])+'</nav>'
def card(title,body,n='file',tone=''):return f'<section class="card {tone}"><div class="section-title"><span class="tile {tone}">{icon(n)}</span><h2>{title}</h2></div>{body}</section>'
def event(time,title,room,tone='teal',end='11:00'):return f'<article class="event {tone}"><div class="time">{time}<small>{end}</small></div><div><h3>{title}</h3><p>{icon("pin")}{room}</p><span class="category">{icon("book")} Course session</span></div></article>'
